with upsert as (
  insert into bandi_news (slug, title, content, status, published_at, updated_at)
  values (
    'decreto-ristori-misure-di-sostegno-economico-previste-dal-governo', 'DECRETO “RISTORI”: Misure di sostegno economico previste dal governo',
    convert_from(decode('','hex'),'utf8'),
    'active', now(), now()
  )
  on conflict (slug) do update set
    title = excluded.title,
    content = excluded.content,
    published_at = excluded.published_at,
    updated_at = excluded.updated_at
  returning (xmax=0) as inserted, slug, length(content) as content_len
) select * from upsert;
